ee:message.ee:set-payload:
%dw 2.0
output application/json
var date = payload[0].Fecha_Creacion as DateTime
---
{
    id: payload[0].Numero_Orden,
    estado: {
        codigo: payload[0].Estado_Orden_Comercial.Codigo,
        nombre: payload[0].Estado_Orden_Comercial.Descripcion
    },
    "fecha-creacion": {
        dia: date.day,
        franja: date.timezone,
        anio: date.year,
        mes: {
            numero: date.month,
            nombre: date as String {format: "MMMM"}
        },
        hora: date as String {format: "hh:mm:ss a"}
    }
}
